#include <queue>


class CBTInserter {
    TreeNode* root;
    queue<TreeNode*> q;

public:
    CBTInserter(TreeNode* root) : root(root) {
        q.push(root);
        while (!q.empty()) {
            TreeNode* node = q.front();
            if (!node->left || !node->right) break;
            q.pop();
            q.push(node->left);
            q.push(node->right);
        }
    }

    int insert(int v) {
        TreeNode* node = q.front();
        TreeNode* newNode = new TreeNode(v);
        if (!node->left)
            node->left = newNode;
        else {
            node->right = newNode;
            q.pop();
            q.push(node->left);
            q.push(node->right);
        }
        return node->val;
    }

    TreeNode* get_root() {
        return root;
    }
};
